from __future__ import annotations

from dataclasses import dataclass


def _non_empty(field: str, label: str) -> None:
    if not field.strip():
        raise ValueError(f"{label} required")


@dataclass(frozen=True)
class UsageEvent:
    usage_id: str
    customer_account_id: str
    license_arn: str
    dimension: str
    quantity: int
    occurred_at_minute: int

    def __post_init__(self) -> None:
        _non_empty(self.usage_id, "usage_id")
        _non_empty(self.customer_account_id, "customer_account_id")
        _non_empty(self.license_arn, "license_arn")
        _non_empty(self.dimension, "dimension")
        if self.quantity <= 0:
            raise ValueError("quantity must be positive")
        if self.occurred_at_minute < 0:
            raise ValueError("occurred_at_minute must be non-negative")

    def primary_subject(self) -> str:
        return f"{self.customer_account_id}:{self.license_arn}:{self.dimension}"


@dataclass(frozen=True)
class Entitlement:
    customer_account_id: str
    license_arn: str
    dimension: str
    active: bool
    expires_at_minute: int

    def __post_init__(self) -> None:
        _non_empty(self.customer_account_id, "customer_account_id")
        _non_empty(self.license_arn, "license_arn")
        _non_empty(self.dimension, "dimension")
        if self.expires_at_minute < 0:
            raise ValueError("expires_at_minute must be non-negative")

    def subject_matches(self, other: Entitlement) -> bool:
        return (
            self.customer_account_id == other.customer_account_id
            and self.license_arn == other.license_arn
            and self.dimension == other.dimension
        )


def usage_event_fingerprint(event: UsageEvent) -> str:
    return "|".join(
        (
            event.usage_id,
            event.customer_account_id,
            event.license_arn,
            event.dimension,
            str(event.quantity),
            str(event.occurred_at_minute),
        )
    )


def entitlement_fingerprint(entitlement: Entitlement) -> str:
    return "|".join(
        (
            entitlement.customer_account_id,
            entitlement.license_arn,
            entitlement.dimension,
            str(entitlement.active),
            str(entitlement.expires_at_minute),
        )
    )


def partition_entitlements_by_activity(entitlements: list[Entitlement]) -> tuple[list[Entitlement], list[Entitlement]]:
    active = [row for row in entitlements if row.active]
    inactive = [row for row in entitlements if not row.active]
    return active, inactive


def assert_positive_quantity(quantity: int) -> None:
    if quantity <= 0:
        raise ValueError("quantity must be positive")

