from __future__ import annotations

"""Batch `BatchMeterUsage`-shaped records with entitlement and dedupe gates."""

from marketplace_models import Entitlement, UsageEvent
from usage_window import (
    MARKETPLACE_METERING_MAX_AGE_MINUTES,
    entitlement_covers_usage_at_submission,
)

MAX_BATCH_SIZE = 25
MAX_USAGE_AGE_MINUTES = MARKETPLACE_METERING_MAX_AGE_MINUTES


def _record(event: UsageEvent) -> dict[str, object]:
    return {
        "usage_id": event.usage_id,
        "customer_account_id": event.customer_account_id,
        "license_arn": event.license_arn,
        "dimension": event.dimension,
        "quantity": event.quantity,
        "timestamp_minute": event.occurred_at_minute,
    }


def _reject(event: UsageEvent, reason: str) -> dict[str, object]:
    return {
        "usage_id": event.usage_id,
        "reason": reason,
        "customer_account_id": event.customer_account_id,
        "license_arn": event.license_arn,
        "dimension": event.dimension,
    }


def _has_active_entitlement(event: UsageEvent, entitlements: list[Entitlement], submission_minute: int) -> bool:
    for row in entitlements:
        if entitlement_covers_usage_at_submission(row, event, submission_minute):
            return True
    return False


def _chunk(records: list[dict[str, object]], size: int) -> list[list[dict[str, object]]]:
    return [records[index : index + size] for index in range(0, len(records), size)]


def build_metering_batches(
    usage_events: list[UsageEvent],
    entitlements: list[Entitlement],
    submission_minute: int,
) -> dict[str, object]:
    accepted: list[dict[str, object]] = []
    rejected: list[dict[str, object]] = []
    skipped_duplicates: list[dict[str, object]] = []
    seen_usage_ids: set[str] = set()

    for event in usage_events:
        if event.usage_id in seen_usage_ids:
            skipped_duplicates.append(_reject(event, "duplicate_usage_id"))
            continue
        seen_usage_ids.add(event.usage_id)

        # Participant hint: reject with "usage_too_old" when event is outside the metering window
        # (see MAX_USAGE_AGE_MINUTES / usage_window.usage_exceeds_metering_window).
        if not _has_active_entitlement(event, entitlements, submission_minute):
            rejected.append(_reject(event, "missing_or_expired_entitlement"))
            continue

        accepted.append(_record(event))

    batches = _chunk(accepted, MAX_BATCH_SIZE)
    return summarize_metering_run(batches, accepted, rejected, skipped_duplicates)


def summarize_metering_run(
    batches: list[list[dict[str, object]]],
    accepted: list[dict[str, object]],
    rejected: list[dict[str, object]],
    skipped_duplicates: list[dict[str, object]],
) -> dict[str, object]:
    return {
        "batch_count": len(batches),
        "accepted_count": len(accepted),
        "rejected_count": len(rejected),
        "skipped_duplicate_count": len(skipped_duplicates),
        "batches": batches,
        "accepted_records": accepted,
        "rejected_records": rejected,
        "skipped_duplicates": skipped_duplicates,
    }


class MarketplaceMeteringGate:
    """Stores seller entitlements and exposes the batching entrypoint used in CI gates."""

    def __init__(self, entitlements: list[Entitlement]) -> None:
        self.entitlements = list(entitlements)

    def build_batches(self, usage_events: list[UsageEvent], submission_minute: int) -> dict[str, object]:
        return build_metering_batches(usage_events, self.entitlements, submission_minute)

