from __future__ import annotations

"""Deterministic helpers for Marketplace SaaS metering time windows (integer minutes)."""

from marketplace_models import Entitlement, UsageEvent

MARKETPLACE_METERING_MAX_AGE_MINUTES = 6 * 60


def usage_age_minutes(submission_minute: int, occurred_at_minute: int) -> int:
    if occurred_at_minute < 0 or submission_minute < 0:
        raise ValueError("minutes must be non-negative")
    if occurred_at_minute > submission_minute:
        raise ValueError("usage cannot occur after submission minute in this kata")
    return submission_minute - occurred_at_minute


def usage_exceeds_metering_window(submission_minute: int, occurred_at_minute: int) -> bool:
    return usage_age_minutes(submission_minute, occurred_at_minute) >= MARKETPLACE_METERING_MAX_AGE_MINUTES


def describe_usage_age(age_minutes: int) -> str:
    hours = age_minutes // 60
    minutes = age_minutes % 60
    if hours and minutes:
        return f"{hours}h{minutes}m before submission"
    if hours:
        return f"{hours}h before submission"
    return f"{minutes}m before submission"


def entitlement_matches_usage_identity(entitlement: Entitlement, event: UsageEvent) -> bool:
    return (
        entitlement.customer_account_id == event.customer_account_id
        and entitlement.license_arn == event.license_arn
        and entitlement.dimension == event.dimension
    )


def entitlement_covers_usage_at_submission(
    entitlement: Entitlement,
    event: UsageEvent,
    submission_minute: int,
) -> bool:
    if not entitlement_matches_usage_identity(entitlement, event):
        return False
    if not entitlement.active:
        return False
    return entitlement.expires_at_minute > submission_minute


def first_covering_entitlement(
    event: UsageEvent,
    entitlements: list[Entitlement],
    submission_minute: int,
) -> Entitlement | None:
    for entitlement in entitlements:
        if entitlement_covers_usage_at_submission(entitlement, event, submission_minute):
            return entitlement
    return None


def batch_partition_indices(total_records: int, chunk_size: int) -> list[tuple[int, int]]:
    if chunk_size <= 0:
        raise ValueError("chunk_size must be positive")
    if total_records < 0:
        raise ValueError("total_records must be non-negative")
    ranges: list[tuple[int, int]] = []
    for start in range(0, total_records, chunk_size):
        end = min(start + chunk_size, total_records)
        ranges.append((start, end))
    return ranges


def metering_audit_tags(batch_count: int, accepted: int, rejected: int, skipped: int) -> dict[str, int]:
    return {
        "batches": batch_count,
        "accepted": accepted,
        "rejected": rejected,
        "skipped_duplicates": skipped,
        "subtotal": accepted + rejected + skipped,
    }


def stable_usage_order_key(event: UsageEvent) -> tuple[str, int, str]:
    return (event.customer_account_id, event.occurred_at_minute, event.usage_id)


def clamp_batch_size(requested: int, maximum: int) -> int:
    if requested <= 0:
        raise ValueError("requested batch size must be positive")
    if maximum <= 0:
        raise ValueError("maximum batch size must be positive")
    return min(requested, maximum)


def replay_backlog_span_minutes(events: list[UsageEvent]) -> int:
    if len(events) < 2:
        return 0
    minutes = [event.occurred_at_minute for event in events]
    return max(minutes) - min(minutes)

